package ma.fstt.dao;
import ma.fstt.model.*; import ma.fstt.persistence.JPAUtil; import java.util.*;
public class ProduitDAO extends BaseDAO { public List<Produit> tous(){try(var em=JPAUtil.getEmf().createEntityManager()){return em.createQuery("SELECT p FROM Produit p ORDER BY p.id DESC",Produit.class).getResultList();}} public Produit trouver(Long id){try(var em=JPAUtil.getEmf().createEntityManager()){return em.find(Produit.class,id);}} public void ajouter(Produit p){tx(em->em.persist(p));} public void modifier(Long id,String n,String d,double prix,int stock){tx(em->{Produit p=em.find(Produit.class,id);if(p!=null){p.setNom(n);p.setDescription(d);p.setPrix(prix);p.setStock(stock);}});} public void supprimer(Long id){tx(em->{Produit p=em.find(Produit.class,id);if(p!=null)em.remove(p);});} }